CREATE TABLE `users` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `username` varchar(255) DEFAULT NULL,
  `phone` varchar(11) NOT NULL,
  `email` varchar(255) NOT NULL,
  `password` longtext NOT NULL,
  `referral_code` varchar(50) DEFAULT NULL,
  `referred_by` varchar(50) DEFAULT NULL,
  `level` int(11) DEFAULT NULL,
  `wallet_balance` decimal(10,2) NOT NULL DEFAULT 0.00,
  `member_type` enum('Created','Pending','Active','Admin','Ban') NOT NULL DEFAULT 'Created',
  `trx_id` varchar(50) DEFAULT NULL,
  `trx_type` enum('Bkash','Nagad','Rocket') DEFAULT NULL,
  `verified_referrals_count` int(11) DEFAULT 0,
  `spins_count` int(11) DEFAULT 0,
  `clicks_count` int(11) DEFAULT 0,
  `ludo_clicks` int(11) DEFAULT 0,
  `spins_plus` int(11) DEFAULT 0,
  `verify_spins` int(11) DEFAULT 5,
  PRIMARY KEY (`id`),
  UNIQUE KEY `email` (`email`),
  UNIQUE KEY `referral_code` (`referral_code`)
) ENGINE=InnoDB AUTO_INCREMENT=6834 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
